import json, sys
import numpy as np
sys.path.insert(0, '/Users/sasha/gkm/arc/crack_lab')
import gkm_arena as A
from perception import connected_components, frame_delta
with open('checkpoint.json') as f: prefix=json.load(f)['final_path']
with open('level9_full_candidate.json') as f: full=json.load(f)['final_path']
suffix=full[len(prefix):]

def pieces(e):
    bs=connected_components(e.frame(), colors=(9,12,14))
    return {'p':tuple(b.top_left for b in bs if b.color==14 and b.size==(4,4)),
            'b':tuple(b.top_left for b in bs if b.color==9 and b.size==(4,4) and b.area==12),
            'c':tuple(b.top_left for b in bs if b.color==12 and b.size==(4,4))}

def trial(base,name,acts):
    c=base.clone(); before=np.asarray(c.frame()).copy()
    for a in acts:
        c.step(*a) if isinstance(a,tuple) else c.step(a)
    d=frame_delta(before,c.frame())
    print(name,acts,'lvl',c.levels_completed,'pieces',pieces(c),'delta',d['count'],d['bbox'])

def probe(env):
    for a in prefix: env.step(a)
    base=env.clone()
    for a in suffix[:37]: base.step(*a) if isinstance(a,list) else base.step(a)
    print('BASE',pieces(base))
    trial(base,'WRAP_52_4',((6,53,19),(6,5,19)))
    trial(base,'FAR_58_4',((6,59,19),(6,5,19)))
    for src in (52,58):
        for key in (1,2,3,4,7):
            trial(base,f'SELECT_{src}_KEY_{key}',((6,src+1,19),key))
levels,path,err=A.run_program('lf52',probe)
print('RUN',levels,len(path),repr(err))
