import json, sys, time
import numpy as np
sys.path.insert(0, '/Users/sasha/gkm/arc/crack_lab')
import gkm_arena as A
with open('checkpoint.json') as f: p=json.load(f)['final_path']
entry=p[:149]; leg=p[149:238]
# Split into maximal key chunks and coordinate pairs, preserving order.
groups=[]; i=0
while i<len(leg):
 if isinstance(leg[i],list): groups.append(('M',(leg[i],leg[i+1]))); i+=2
 else:
  j=i
  while j<len(leg) and not isinstance(leg[j],list): j+=1
  groups.append(('K',tuple(leg[i:j]))); i=j
steps=0; started=time.monotonic()
def step(e,a):
 global steps
 e.step(*a) if isinstance(a,(list,tuple)) else e.step(a); steps+=1
 due=steps/300; elapsed=time.monotonic()-started
 if due>elapsed: time.sleep(due-elapsed)
def key(e): return np.asarray(e.frame())[1:].tobytes()
def probe(env):
 for a in entry: env.step(a)
 node=env.clone(); out=[]; ki=0
 for typ,data in groups:
  if typ=='M':
   for a in data: step(node,a); out.append(tuple(a))
   continue
  ki+=1; target=node.clone()
  for a in data: step(target,a)
  target_key=key(target); chosen=list(data); changed=True
  while changed:
   changed=False
   for j in range(len(chosen)):
    c=node.clone()
    for a in chosen[:j]+chosen[j+1:]: step(c,a)
    if key(c)==target_key: chosen.pop(j); changed=True; break
  for a in chosen: step(node,a); out.append(a)
  print('KEY',ki,len(data),'->',len(chosen),tuple(chosen),'exact',key(node)==target_key,flush=True)
 print('DONE','level',node.levels_completed,'len',len(out),'saved',len(leg)-len(out),'steps',steps,flush=True)
levels,path,err=A.run_program('lf52',probe)
print('RUN',levels,len(path),repr(err))
